package com.jiugeng.erp.supplier;
import static com.jiugeng.erp.supplier.SupplierTypes.*;import java.sql.*;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository class SupplierRepository{private final JdbcClient jdbc;SupplierRepository(JdbcClient jdbc){this.jdbc=jdbc;}
List<View> list(String q,Status status,int page,int size){String term=q==null?"":q.trim().toUpperCase(Locale.ROOT);return jdbc.sql("""
 SELECT * FROM supplier WHERE (:term='' OR UPPER(name) LIKE :like OR UPPER(COALESCE(phone,'')) LIKE :like OR UPPER(COALESCE(wechat_id,'')) LIKE :like)
 AND (:status IS NULL OR status=:status) ORDER BY name,id LIMIT :size OFFSET :offset
 """).param("term",term).param("like","%"+term+"%").param("status",status==null?null:status.name()).param("size",size).param("offset",page*size).query(this::view).list();}
long count(String q,Status status){String term=q==null?"":q.trim().toUpperCase(Locale.ROOT);return jdbc.sql("SELECT COUNT(*) FROM supplier WHERE (:term='' OR UPPER(name) LIKE :like OR UPPER(COALESCE(phone,'')) LIKE :like OR UPPER(COALESCE(wechat_id,'')) LIKE :like) AND (:status IS NULL OR status=:status)").param("term",term).param("like","%"+term+"%").param("status",status==null?null:status.name()).query(Long.class).single();}
Optional<View> find(String id){return jdbc.sql("SELECT * FROM supplier WHERE id=:id").param("id",id).query(this::view).optional();}
void insert(String id,Input i,String actor){jdbc.sql("INSERT INTO supplier(id,name,contact_person,phone,wechat_id,source_url,qr_image_url,qr_image_asset_id,remark,status,created_by,updated_by) VALUES(:id,:name,:contact,:phone,:wechat,:url,:qrUrl,:qr,:remark,:status,:actor,:actor)").param("id",id).param("name",i.name()).param("contact",i.contactPerson()).param("phone",i.phone()).param("wechat",i.wechatId()).param("url",i.sourceUrl()).param("qrUrl",i.qrImageUrl()).param("qr",i.qrImageId()).param("remark",i.remark()).param("status",i.status().name()).param("actor",actor).update();}
int update(String id,Input i,String actor,long version){return jdbc.sql("UPDATE supplier SET name=:name,contact_person=:contact,phone=:phone,wechat_id=:wechat,source_url=:url,qr_image_url=:qrUrl,qr_image_asset_id=:qr,remark=:remark,status=:status,version=version+1,updated_by=:actor,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:version").param("id",id).param("name",i.name()).param("contact",i.contactPerson()).param("phone",i.phone()).param("wechat",i.wechatId()).param("url",i.sourceUrl()).param("qrUrl",i.qrImageUrl()).param("qr",i.qrImageId()).param("remark",i.remark()).param("status",i.status().name()).param("actor",actor).param("version",version).update();}
boolean active(String id){return jdbc.sql("SELECT COUNT(*) FROM supplier WHERE id=:id AND status='ACTIVE'").param("id",id).query(Integer.class).single()>0;}
List<LinkView> links(String table,String ownerColumn,String ownerId){String sql="SELECT r.id,r."+ownerColumn+" owner_id,r.supplier_id,s.name,s.status,r.purchase_url,r.remark,r.primary_slot,r.updated_at FROM "+table+" r JOIN supplier s ON s.id=r.supplier_id WHERE r."+ownerColumn+"=:owner ORDER BY CASE WHEN r.primary_slot='PRIMARY' THEN 0 ELSE 1 END,s.name";return jdbc.sql(sql).param("owner",ownerId).query(this::link).list();}
void deleteLinks(String table,String ownerColumn,String ownerId){jdbc.sql("DELETE FROM "+table+" WHERE "+ownerColumn+"=:owner").param("owner",ownerId).update();}
void insertLink(String table,String ownerColumn,String ownerId,LinkInput i,String actor){jdbc.sql("INSERT INTO "+table+"(id,"+ownerColumn+",supplier_id,purchase_url,remark,primary_slot,created_by,updated_by) VALUES(:id,:owner,:supplier,:url,:remark,:primary,:actor,:actor)").param("id",UUID.randomUUID().toString()).param("owner",ownerId).param("supplier",i.supplierId()).param("url",i.purchaseUrl()).param("remark",i.remark()).param("primary",i.primary()?"PRIMARY":null).param("actor",actor).update();}
private View view(ResultSet r,int n)throws SQLException{return new View(r.getString("id"),r.getString("name"),r.getString("contact_person"),r.getString("phone"),r.getString("wechat_id"),r.getString("source_url"),r.getString("qr_image_url"),r.getString("qr_image_asset_id"),r.getString("remark"),Status.valueOf(r.getString("status")),r.getLong("version"),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
private LinkView link(ResultSet r,int n)throws SQLException{return new LinkView(r.getString("id"),r.getString("owner_id"),r.getString("supplier_id"),r.getString("name"),Status.valueOf(r.getString("status")),r.getString("purchase_url"),r.getString("remark"),"PRIMARY".equals(r.getString("primary_slot")),r.getTimestamp("updated_at").toInstant());}
}
